// --- Search query language ------------------------------------------------
// Grammar (precedence: NOT > AND > OR; adjacent terms imply AND):
//   expr   := or
//   or     := and (OR and)*
//   and    := not ( (AND)? not )*        // implicit AND between adjacent terms
//   not    := NOT not | primary
//   primary:= '(' expr ')' | #tag | "phrase" | word
// A term is either a #tag (exact tag match) or text (substring in title,
// link, description, note), case-insensitive.
function tokenize(s){
  const toks=[]; let i=0;
  while(i<s.length){
    const c=s[i];
    if(/\s/.test(c)){ i++; continue; }
    if(c==='('){ toks.push({t:'('}); i++; continue; }
    if(c===')'){ toks.push({t:')'}); i++; continue; }
    if(c==='"'){ let j=i+1; let v=''; while(j<s.length && s[j]!=='"'){ v+=s[j++]; } i=j+1; toks.push({t:'term', kind:'text', v:v.toLowerCase()}); continue; }
    if(c==='#'){ let j=i+1; let v=''; while(j<s.length && /[^\s()]/.test(s[j])){ v+=s[j++]; } i=j; toks.push({t:'term', kind:'tag', v:v.toLowerCase()}); continue; }
    // bare word (until whitespace or paren)
    let j=i; let v=''; while(j<s.length && /[^\s()]/.test(s[j])){ v+=s[j++]; } i=j;
    if(v==='AND'||v==='OR'||v==='NOT'){ toks.push({t:v}); }
    else { toks.push({t:'term', kind:'text', v:v.toLowerCase()}); }
  }
  return toks;
}
function parseQuery(toks){
  let p=0;
  const peek=()=>toks[p];
  const isTermStart=()=>{ const k=peek(); return k && (k.t==='term'||k.t==='('||k.t==='NOT'); };
  function parseOr(){
    let node=parseAnd();
    while(peek() && peek().t==='OR'){ p++; node={op:'or', l:node, r:parseAnd()}; }
    return node;
  }
  function parseAnd(){
    let node=parseNot();
    while(peek() && (peek().t==='AND' || (peek().t!=='OR' && peek().t!==')' && isTermStart()))){
      if(peek().t==='AND') p++;
      node={op:'and', l:node, r:parseNot()};
    }
    return node;
  }
  function parseNot(){
    if(peek() && peek().t==='NOT'){ p++; return {op:'not', c:parseNot()}; }
    return parsePrimary();
  }
  function parsePrimary(){
    const k=peek();
    if(!k) throw new Error('unexpected end');
    if(k.t==='('){ p++; const n=parseOr(); if(!peek()||peek().t!==')') throw new Error('missing )'); p++; return n; }
    if(k.t==='term'){ p++; return {op:'term', kind:k.kind, v:k.v}; }
    throw new Error('unexpected '+k.t);
  }
  const tree=parseOr();
  if(p!==toks.length) throw new Error('trailing input');
  return tree;
}
function evalNode(node, b){
  switch(node.op){
    case 'or':  return evalNode(node.l,b) || evalNode(node.r,b);
    case 'and': return evalNode(node.l,b) && evalNode(node.r,b);
    case 'not': return !evalNode(node.c,b);
    case 'term':
      if(node.kind==='tag') return b.tags.some(t=>t.toLowerCase()===node.v);
      const hay=[b.title, b.url, b.desc, b.note].join(' ').toLowerCase();
      return hay.includes(node.v);
  }
  return false;
}

